describe('Reading Order Accessibility', () => {
  beforeEach(() => {
    cy.visit('/');
    cy.injectAxe();
  });

  it('should have correct reading order matching visual order', () => {
    // Get all focusable elements in tab order
    cy.get('button, a, input, select, textarea, [tabindex]:not([tabindex="-1"])').then(($elements) => {
      const tabOrder = [];

      $elements.each((index, element) => {
        const tabindex = Cypress.$(element).attr('tabindex');
        const rect = element.getBoundingClientRect();

        tabOrder.push({
          element: element.tagName,
          tabindex: tabindex ? parseInt(tabindex) : 0,
          top: rect.top,
          left: rect.left,
          text: Cypress.$(element).text().substring(0, 20)
        });
      });

      // Verify no positive tabindex values (anti-pattern)
      const positiveTabindices = tabOrder.filter(item => item.tabindex > 0);
      expect(positiveTabindices).to.have.length(0);

      // Verify reading order follows visual flow (top to bottom, left to right)
      const sortedByVisualOrder = [...tabOrder].sort((a, b) => {
        if (Math.abs(a.top - b.top) > 50) {
          return a.top - b.top;
        }
        return a.left - b.left;
      });

      // Check that DOM order roughly matches visual order
      const visualOrderIndices = tabOrder.map(item => sortedByVisualOrder.indexOf(item));
      const isSequential = visualOrderIndices.every((val, i, arr) => 
        i === 0 || val > arr[i - 1] || Math.abs(val - arr[i - 1]) <= 2
      );

      expect(isSequential).to.be.true;
    });
  });

  it('should pass axe accessibility checks for reading order', () => {
    cy.checkA11y(null, {
      rules: {
        'tabindex': { enabled: true }
      }
    });
  });

  it('should maintain reading order when navigating with keyboard', () => {
    cy.get('body').tab();
    cy.focused().then(($firstFocused) => {
      const firstElement = $firstFocused[0];
      expect(firstElement).to.exist;
    });

    cy.get('body').tab();
    cy.focused().then(($secondFocused) => {
      const secondElement = $secondFocused[0];
      expect(secondElement).to.not.equal(firstElement);
    });

    // Verify shift+tab goes backward
    cy.get('body').tab({ shift: true });
    cy.focused().then(($previousFocused) => {
      expect($previousFocused[0]).to.equal(firstElement);
    });
  });

  it('should handle edge case of hidden elements not affecting reading order', () => {
    cy.get('[style*="display: none"], [hidden]').then(($hiddenElements) => {
      // Verify hidden elements are not in tab order
      $hiddenElements.each((index, element) => {
        const tabindex = Cypress.$(element).attr('tabindex');
        if (tabindex) {
          expect(parseInt(tabindex)).to.equal(-1);
        }
      });
    });

    // Verify visible elements are still in correct order
    cy.get('body').tab();
    cy.focused().then(($focused) => {
      const isVisible = Cypress.$(($focused[0])).is(':visible');
      expect(isVisible).to.be.true;
    });
  });
});
